"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group"
import { cn } from "@/lib/utils"
import { RemoveCaseIcon } from "@/components/mockups/transfer-routing/icons"

export function CaseField({
  cases,
  overlapping,
  onAdd,
  onRemove,
}: {
  cases: string[]
  overlapping: Set<string>
  onAdd: (value: string) => void
  onRemove: (value: string) => void
}) {
  const [draft, setDraft] = React.useState("")

  function commit() {
    const value = draft.trim()
    if (!value || cases.includes(value)) return
    onAdd(value)
    setDraft("")
  }

  return (
    <InputGroup>
      {cases.length ? (
        <InputGroupAddon align="block-start" className="flex-wrap">
          {cases.map((value) => (
            <Button
              key={value}
              type="button"
              variant="secondary"
              size="xs"
              onClick={() => onRemove(value)}
              className={cn(
                overlapping.has(value) &&
                  "bg-warning/20 text-warning-foreground hover:bg-warning/30",
              )}
            >
              {value}
              <RemoveCaseIcon data-icon="inline-end" />
            </Button>
          ))}
        </InputGroupAddon>
      ) : null}

      <InputGroupInput
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          if (event.key !== "Enter") return
          event.preventDefault()
          commit()
        }}
        onBlur={commit}
        placeholder="Add a reason and press Enter"
      />
    </InputGroup>
  )
}

"use client"

import {
  Alert02Icon,
  ArrowDown01Icon,
  Cancel01Icon,
  CheckmarkCircle02Icon,
  Delete02Icon,
  DragDropVerticalIcon,
  PlusSignIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

export const ReorderIcon = icon(DragDropVerticalIcon, "ReorderIcon")
export const RemoveCaseIcon = icon(Cancel01Icon, "RemoveCaseIcon")
export const CloseIcon = icon(Cancel01Icon, "CloseIcon")
export const DeleteRouteIcon = icon(Delete02Icon, "DeleteRouteIcon")
export const AddRouteIcon = icon(PlusSignIcon, "AddRouteIcon")
export const SetDefaultIcon = icon(CheckmarkCircle02Icon, "SetDefaultIcon")
export const ExpandIcon = icon(ArrowDown01Icon, "ExpandIcon")

export const OverlapIcon = icon(Alert02Icon, "OverlapIcon")

"use client"

import * as React from "react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader } from "@/components/ui/card"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import { Input } from "@/components/ui/input"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"
import {
  KEYPAD_KEYS,
  TRANSFER_MODES,
  effectiveMode,
  overriddenFields,
  type Route,
  type SharedSettings,
  type TransferMode,
  type WorkingHours,
} from "@/lib/mockups/transfer-routing-data"
import { CaseField } from "@/components/mockups/transfer-routing/case-field"
import {
  DeleteRouteIcon,
  ExpandIcon,
  ReorderIcon,
  SetDefaultIcon,
} from "@/components/mockups/transfer-routing/icons"

export function RouteCard({
  route,
  isDefault,
  shared,
  overlappingCases,
  hasOverlap,
  dragging,
  armed,
  settingsOpen,
  onChange,
  onDelete,
  onSetDefault,
  onArm,
  onDragStart,
  onDragEnter,
  onDragEnd,
}: {
  route: Route
  isDefault: boolean
  shared: SharedSettings
  overlappingCases: Set<string>
  hasOverlap: boolean
  dragging: boolean
  /** The grip is held, so this card may start a drag. */
  armed: boolean
  settingsOpen: boolean
  onChange: (next: Route) => void
  onDelete: () => void
  onSetDefault: () => void
  onArm: (armed: boolean) => void
  onDragStart: () => void
  onDragEnter: () => void
  onDragEnd: () => void
}) {
  const overrides = overriddenFields(route)
  const mode = effectiveMode(route, shared)

  function patch(next: Partial<Route>) {
    onChange({ ...route, ...next })
  }

  function patchOverride(next: Partial<Route["overrides"]>) {
    onChange({ ...route, overrides: { ...route.overrides, ...next } })
  }

  return (
    <Card
      draggable={armed}
      onDragOver={(event) => event.preventDefault()}
      onDragEnter={onDragEnter}
      onDragEnd={onDragEnd}
      onDrop={onDragEnd}
      onDragStart={onDragStart}
      className={cn(
        "gap-4",
        hasOverlap && "ring-warning",
        dragging && "opacity-60",
      )}
    >
      <CardHeader className="flex items-center gap-2">
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={`Reorder ${route.name || "route"}`}
          className="cursor-grab active:cursor-grabbing"
          onPointerDown={() => onArm(true)}
          onPointerUp={() => onArm(false)}
        >
          <ReorderIcon />
        </Button>

        <Input
          value={route.name}
          onChange={(event) => patch({ name: event.target.value })}
          placeholder="Route name"
          aria-label="Route name"
          className="max-w-50"
        />

        {isDefault ? (
          <Badge variant="secondary">Default</Badge>
        ) : (
          <Button variant="ghost" size="sm" onClick={onSetDefault}>
            <SetDefaultIcon />
            Set as default
          </Button>
        )}

        <div className="ms-auto">
          <Button
            variant="ghost"
            size="icon-sm"
            onClick={onDelete}
            disabled={isDefault}
            aria-label={
              isDefault
                ? "The default route can't be deleted"
                : `Delete ${route.name || "route"}`
            }
            title={
              isDefault
                ? "The default route can't be deleted — set another route as default first."
                : undefined
            }
          >
            <DeleteRouteIcon />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="flex flex-col gap-4">
        <div className="flex flex-wrap items-end gap-4">
          <Field className="min-w-60 flex-1">
            <FieldLabel htmlFor={`${route.id}-destination`}>
              Destination number
            </FieldLabel>
            <Input
              id={`${route.id}-destination`}
              value={route.destination}
              onChange={(event) => patch({ destination: event.target.value })}
              placeholder="+966 11 000 0000"
            />
          </Field>

          <Field className="w-40">
            <FieldLabel htmlFor={`${route.id}-key`}>Keypad shortcut</FieldLabel>
            <Select
              value={route.keypadKey}
              onValueChange={(value) => patch({ keypadKey: value })}
            >
              <SelectTrigger id={`${route.id}-key`}>
                <SelectValue placeholder="None" />
              </SelectTrigger>
              <SelectContent position="popper">
                {KEYPAD_KEYS.map((key) => (
                  <SelectItem key={key} value={key}>
                    Press {key}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
        </div>

        <Field>
          <FieldTitle>When to use this route</FieldTitle>
          <CaseField
            cases={route.cases}
            overlapping={overlappingCases}
            onAdd={(value) => patch({ cases: [...route.cases, value] })}
            onRemove={(value) =>
              patch({ cases: route.cases.filter((item) => item !== value) })
            }
          />
        </Field>

        <Collapsible defaultOpen={settingsOpen} className="flex flex-col gap-3">
          <CollapsibleTrigger asChild>
            <Button variant="ghost" size="sm" className="w-fit">
              <ExpandIcon className="transition-transform duration-200 ease-out-cubic group-aria-expanded/button:rotate-180 motion-reduce:transition-none" />
              Settings for this route
              {overrides.length ? (
                <Badge variant="secondary">{overrides.length} overridden</Badge>
              ) : (
                <span className="text-muted-foreground">using shared</span>
              )}
            </Button>
          </CollapsibleTrigger>

          <CollapsibleContent className="flex flex-col gap-4 rounded-lg bg-muted p-4">
            <OverrideRow
              title="Transfer mode"
              shared={
                TRANSFER_MODES.find(
                  (item) => item.value === shared.transferMode,
                )?.label ?? ""
              }
              overridden={route.overrides.transferMode !== null}
              onToggle={(on) =>
                patchOverride({ transferMode: on ? shared.transferMode : null })
              }
            >
              <Select
                value={route.overrides.transferMode ?? shared.transferMode}
                onValueChange={(value) =>
                  patchOverride({ transferMode: value as TransferMode })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent position="popper">
                  {TRANSFER_MODES.map((item) => (
                    <SelectItem key={item.value} value={item.value}>
                      {item.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </OverrideRow>

            <OverrideRow
              title="Message before transferring"
              shared={shared.messageBeforeTransfer}
              overridden={route.overrides.messageBeforeTransfer !== null}
              onToggle={(on) =>
                patchOverride({
                  messageBeforeTransfer: on
                    ? shared.messageBeforeTransfer
                    : null,
                })
              }
            >
              <Textarea
                rows={2}
                value={route.overrides.messageBeforeTransfer ?? ""}
                onChange={(event) =>
                  patchOverride({ messageBeforeTransfer: event.target.value })
                }
              />
            </OverrideRow>

            <OverrideRow
              title="Working hours"
              shared={`${shared.workingHours.start}–${shared.workingHours.end}, and what plays outside them`}
              overridden={route.overrides.workingHours !== null}
              onToggle={(on) =>
                patchOverride({ workingHours: on ? shared.workingHours : null })
              }
            >
              <WorkingHoursFields
                value={route.overrides.workingHours ?? shared.workingHours}
                idPrefix={route.id}
                onChange={(workingHours) => patchOverride({ workingHours })}
              />
            </OverrideRow>

            {mode === "warm" ? (
              <OverrideRow
                title="Warm summary prompt"
                shared={shared.warmSummaryPrompt}
                overridden={route.overrides.warmSummaryPrompt !== null}
                onToggle={(on) =>
                  patchOverride({
                    warmSummaryPrompt: on ? shared.warmSummaryPrompt : null,
                  })
                }
              >
                <Textarea
                  rows={3}
                  value={route.overrides.warmSummaryPrompt ?? ""}
                  onChange={(event) =>
                    patchOverride({ warmSummaryPrompt: event.target.value })
                  }
                />
              </OverrideRow>
            ) : null}
          </CollapsibleContent>
        </Collapsible>
      </CardContent>
    </Card>
  )
}

function OverrideRow({
  title,
  shared,
  overridden,
  onToggle,
  children,
}: {
  title: string
  shared: string
  overridden: boolean
  onToggle: (on: boolean) => void
  children: React.ReactNode
}) {
  return (
    <Field className="gap-3">
      <Field orientation="horizontal">
        <FieldContent>
          <FieldTitle>{title}</FieldTitle>
          {overridden ? null : (
            <FieldDescription>Shared — {shared}</FieldDescription>
          )}
        </FieldContent>
        <Switch
          checked={overridden}
          onCheckedChange={onToggle}
          aria-label={`Override ${title.toLowerCase()} for this route`}
        />
      </Field>
      {overridden ? children : null}
    </Field>
  )
}

export function WorkingHoursFields({
  value,
  idPrefix,
  onChange,
}: {
  value: WorkingHours
  idPrefix: string
  onChange: (next: WorkingHours) => void
}) {
  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-end gap-3">
        <Field className="min-w-32 flex-1">
          <FieldLabel htmlFor={`${idPrefix}-start`}>Opens</FieldLabel>
          <Input
            id={`${idPrefix}-start`}
            type="time"
            value={value.start}
            onChange={(event) =>
              onChange({ ...value, start: event.target.value })
            }
          />
        </Field>
        <Field className="min-w-32 flex-1">
          <FieldLabel htmlFor={`${idPrefix}-end`}>Closes</FieldLabel>
          <Input
            id={`${idPrefix}-end`}
            type="time"
            value={value.end}
            onChange={(event) =>
              onChange({ ...value, end: event.target.value })
            }
          />
        </Field>
      </div>
      <Field>
        <FieldLabel htmlFor={`${idPrefix}-outside`}>
          Outside-hours message
        </FieldLabel>
        <Textarea
          id={`${idPrefix}-outside`}
          rows={2}
          value={value.outsideHoursMessage}
          onChange={(event) =>
            onChange({ ...value, outsideHoursMessage: event.target.value })
          }
        />
      </Field>
    </div>
  )
}

"use client"

import {
  Field,
  FieldDescription,
  FieldLabel,
  FieldTitle,
} from "@/components/ui/field"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Textarea } from "@/components/ui/textarea"
import {
  OUTBOUND_TRUNKS,
  TRANSFER_MODES,
  type SharedSettings as SharedSettingsValue,
  type TransferMode,
} from "@/lib/mockups/transfer-routing-data"
import { WorkingHoursFields } from "@/components/mockups/transfer-routing/route-card"

export function SharedSettings({
  value,
  warmInUse,
  onChange,
}: {
  value: SharedSettingsValue
  /** Any route can transfer warm, and a route overridden to warm still inherits this prompt. */
  warmInUse: boolean
  onChange: (next: SharedSettingsValue) => void
}) {
  function patch(next: Partial<SharedSettingsValue>) {
    onChange({ ...value, ...next })
  }

  return (
    <div className="flex flex-col gap-6">
      <Field>
        <FieldTitle>Transfer mode</FieldTitle>
        <Select
          value={value.transferMode}
          onValueChange={(mode) =>
            patch({ transferMode: mode as TransferMode })
          }
        >
          <SelectTrigger id="shared-mode">
            <SelectValue />
          </SelectTrigger>
          <SelectContent position="popper">
            {TRANSFER_MODES.map((item) => (
              <SelectItem key={item.value} value={item.value}>
                {item.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </Field>

      <Field>
        <FieldLabel htmlFor="shared-message">
          Message before transferring
        </FieldLabel>
        <Textarea
          id="shared-message"
          rows={2}
          value={value.messageBeforeTransfer}
          onChange={(event) =>
            patch({ messageBeforeTransfer: event.target.value })
          }
        />
      </Field>

      <Field>
        <FieldTitle>Working hours</FieldTitle>
        <div className="rounded-lg bg-muted p-4">
          <WorkingHoursFields
            value={value.workingHours}
            idPrefix="shared"
            onChange={(workingHours) => patch({ workingHours })}
          />
        </div>
      </Field>

      {warmInUse ? (
        <Field>
          <FieldLabel htmlFor="shared-summary">Warm summary prompt</FieldLabel>
          <Textarea
            id="shared-summary"
            rows={3}
            value={value.warmSummaryPrompt}
            onChange={(event) =>
              patch({ warmSummaryPrompt: event.target.value })
            }
          />
        </Field>
      ) : null}

      <Field>
        <FieldLabel htmlFor="shared-trunk">Preferred outbound trunk</FieldLabel>
        <Select
          value={value.outboundTrunk}
          onValueChange={(outboundTrunk) => patch({ outboundTrunk })}
        >
          <SelectTrigger id="shared-trunk">
            <SelectValue />
          </SelectTrigger>
          <SelectContent position="popper">
            {OUTBOUND_TRUNKS.map((trunk) => (
              <SelectItem key={trunk} value={trunk}>
                {trunk}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        <FieldDescription>
          Every route dials out on this trunk. It can&apos;t be set per route.
        </FieldDescription>
      </Field>
    </div>
  )
}

"use client"

import * as React from "react"

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert"
import { Button } from "@/components/ui/button"
import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer"
import { FieldSeparator } from "@/components/ui/field"
import {
  DEFAULT_ROUTE_ID,
  KEYPAD_KEYS,
  ROUTES,
  SHARED_SETTINGS,
  effectiveMode,
  emptyRoute,
  findOverlaps,
  overlappingCases,
  overriddenFields,
  type Route,
  type SharedSettings as SharedSettingsValue,
} from "@/lib/mockups/transfer-routing-data"
import { RouteCard } from "@/components/mockups/transfer-routing/route-card"
import { SharedSettings } from "@/components/mockups/transfer-routing/shared-settings"
import {
  AddRouteIcon,
  CloseIcon,
  OverlapIcon,
} from "@/components/mockups/transfer-routing/icons"

export function TransferToolDrawer() {
  const [open, setOpen] = React.useState(true)
  const [routes, setRoutes] = React.useState<Route[]>(ROUTES)
  const [defaultRouteId, setDefaultRouteId] = React.useState(DEFAULT_ROUTE_ID)
  const [shared, setShared] =
    React.useState<SharedSettingsValue>(SHARED_SETTINGS)

  const [armedId, setArmedId] = React.useState<string | null>(null)
  const [draggingId, setDraggingId] = React.useState<string | null>(null)

  const overlaps = findOverlaps(routes)
  const flagged = overlappingCases(overlaps)
  const overlappingRouteIds = new Set(overlaps.flatMap((item) => item.routeIds))

  const firstOverriding = routes.find((route) => overriddenFields(route).length)

  function addRoute() {
    const taken = new Set(routes.map((route) => route.keypadKey))
    const free = KEYPAD_KEYS.find((key) => !taken.has(key)) ?? ""
    setRoutes([...routes, emptyRoute(`route-${routes.length + 1}`, free)])
  }

  function move(fromId: string, toId: string) {
    if (fromId === toId) return

    const next = [...routes]
    const from = next.findIndex((route) => route.id === fromId)
    const to = next.findIndex((route) => route.id === toId)
    if (from < 0 || to < 0) return

    next.splice(to, 0, ...next.splice(from, 1))
    setRoutes(next)
  }

  return (
    <Drawer
      open={open}
      onOpenChange={setOpen}
      direction="right"
      // Cards own drag-to-reorder, so the drawer must not read a drag as dismiss.
      handleOnly
    >
      <DrawerTrigger asChild>
        <Button variant="outline">Configure Transfer tool</Button>
      </DrawerTrigger>

      <DrawerContent className="sm:max-w-3xl!">
        <DrawerHeader className="flex flex-row items-start justify-between gap-4 border-b">
          <div className="flex flex-col gap-0.5">
            <DrawerTitle>Transfer to a Human Agent</DrawerTitle>
            <DrawerDescription>
              Send the caller to a human based on why they&apos;re calling.
            </DrawerDescription>
          </div>
          <DrawerClose asChild>
            <Button variant="ghost" size="icon-sm" aria-label="Close">
              <CloseIcon />
            </Button>
          </DrawerClose>
        </DrawerHeader>

        <div className="flex min-h-0 flex-1 flex-col gap-6 overflow-y-auto p-4">
          <section className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <h3 className="text-base font-medium">Routing options</h3>
              <p className="text-sm text-muted-foreground">
                Add a destination for every reason a caller might need a human.
                The agent picks the route that best matches what the caller
                said.
              </p>
            </div>

            {routes.map((route) => (
              <RouteCard
                key={route.id}
                route={route}
                isDefault={route.id === defaultRouteId}
                shared={shared}
                overlappingCases={flagged}
                hasOverlap={overlappingRouteIds.has(route.id)}
                dragging={draggingId === route.id}
                armed={armedId === route.id}
                settingsOpen={route.id === firstOverriding?.id}
                onChange={(next) =>
                  setRoutes(
                    routes.map((item) => (item.id === next.id ? next : item)),
                  )
                }
                onDelete={() =>
                  setRoutes(routes.filter((item) => item.id !== route.id))
                }
                onSetDefault={() => setDefaultRouteId(route.id)}
                onArm={(armed) => setArmedId(armed ? route.id : null)}
                onDragStart={() => setDraggingId(route.id)}
                onDragEnter={() => {
                  if (draggingId) move(draggingId, route.id)
                }}
                onDragEnd={() => {
                  setDraggingId(null)
                  setArmedId(null)
                }}
              />
            ))}

            {overlaps.map((overlap) => {
              const [first, second] = overlap.routeIds.map(
                (id) => routes.find((route) => route.id === id)?.name ?? "",
              )

              return (
                <Alert
                  key={`${overlap.cases[0]}-${overlap.cases[1]}`}
                  className="bg-warning/10 text-warning-foreground"
                >
                  <OverlapIcon />
                  <AlertTitle>
                    &ldquo;{overlap.cases[0]}&rdquo; in {first} sounds similar
                    to &ldquo;{overlap.cases[1]}&rdquo; in {second}
                  </AlertTitle>
                  <AlertDescription className="text-warning-foreground/80">
                    The agent may have trouble telling these two routes apart.
                    Try making one more specific.
                  </AlertDescription>
                </Alert>
              )
            })}

            <Button variant="outline" onClick={addRoute} className="w-full">
              <AddRouteIcon />
              Add another route
            </Button>
          </section>

          <FieldSeparator />

          <section className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <h3 className="text-base font-medium">Shared settings</h3>
              <p className="text-sm text-muted-foreground">
                Every route uses these unless it overrides them in its own
                settings.
              </p>
            </div>

            <SharedSettings
              value={shared}
              warmInUse={routes.some(
                (route) => effectiveMode(route, shared) === "warm",
              )}
              onChange={setShared}
            />
          </section>
        </div>

        <DrawerFooter className="flex-row justify-end border-t bg-muted/50">
          <DrawerClose asChild>
            <Button variant="outline">Cancel</Button>
          </DrawerClose>
          <Button onClick={() => setOpen(false)}>Save changes</Button>
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  )
}

"use client"

import { HugeiconsIcon, type IconSvgElement } from "@hugeicons/react"

/** No size of its own, so primitives size it through their `[&_svg]:size-4` rules. */
export function icon(glyph: IconSvgElement, displayName: string) {
  const Icon = (
    props: Omit<React.ComponentProps<typeof HugeiconsIcon>, "icon">,
  ) => <HugeiconsIcon icon={glyph} strokeWidth={1.8} {...props} />
  Icon.displayName = displayName
  return Icon
}

"use client"

import * as React from "react"
import Link from "next/link"

import { Button } from "@/components/ui/button"
import { BackIcon } from "@/components/shell/workspace-icons"

/** 48px tall: `AppShell` starts its fixed sidebar under it. */
export function MockupShell({
  title,
  actions,
  children,
}: {
  title: string
  /** Kept for the callers that pass it; the bar shows the title alone. */
  eyebrow?: string
  actions?: React.ReactNode
  children: React.ReactNode
}) {
  return (
    <div className="flex min-h-full grow flex-col bg-sidebar">
      <header className="sticky top-0 z-nav flex h-12 shrink-0 items-center gap-2 border-b bg-sidebar px-3">
        <Button aria-label="All mockups" asChild size="icon-sm" variant="ghost">
          <Link href="/">
            <BackIcon />
          </Link>
        </Button>
        <span
          className="min-w-0 flex-1 truncate text-sm font-medium"
          title={title}
        >
          {title}
        </span>
        {actions ? (
          <div className="flex shrink-0 items-center gap-1.5">{actions}</div>
        ) : null}
      </header>

      <div className="flex min-h-0 flex-1 flex-col">{children}</div>
    </div>
  )
}

